1	/**
2	 * review.js — Handles the Review Games page (Game Titles & Territory Estimation).
3	 */
4	
5	let reviewBoard = null;
6	let currentGameData = null;
7	let currentMoveIndex = 0;
8	let showTerritory = false;
9	let winrateChart = null;
10	let winrateBlack = [];   // base series: Black's win % per move
11	let winrateSide = 1;     // perspective shown: 1 = Black, 2 = White
12	
13	document.addEventListener('DOMContentLoaded', () => {
14	    loadGamesList();
15	
16	    document.getElementById('btn-refresh').addEventListener('click', loadGamesList);
17	
18	    document.getElementById('btn-first').addEventListener('click', () => jumpToMove(0));
19	    document.getElementById('btn-prev').addEventListener('click', () => jumpToMove(currentMoveIndex - 1));
20	    document.getElementById('btn-next').addEventListener('click', () => jumpToMove(currentMoveIndex + 1));
