35	
36	    const btnSideBlack = document.getElementById('winrate-side-black');
37	    const btnSideWhite = document.getElementById('winrate-side-white');
38	    if (btnSideBlack) btnSideBlack.addEventListener('click', () => setWinrateSide(1));
39	    if (btnSideWhite) btnSideWhite.addEventListener('click', () => setWinrateSide(2));
