49	async function loadGamesList() {
50	    const list = document.getElementById('review-games-list');
51	    try {
52	        const res = await fetch('/training/api/games');
53	        const groupedGames = await res.json();
54	        list.innerHTML = '';
55	
56	        if (groupedGames.length === 0) {
57	            list.innerHTML = '<p style="color: var(--text-muted); text-align: center;">No games available.</p>';
58	            return;
59	        }
60	
61	        groupedGames.forEach((group, groupIdx) => {
62	            const details = document.createElement('details');
63	            details.className = 'iteration-group';
64	            if (groupIdx === 0) details.open = true;
65	
66	            let evalCount = 0;
67	            let aiWins = 0;
68	            group.games.forEach(game => {
69	                if (game.is_eval && game.network_color !== undefined) {
70	                    evalCount++;
71	                    if (game.winner === game.network_color) {
72	                        aiWins++;
73	                    }
74	                }
75	            });
76	
77	            let winrateHtml = '';
78	            if (evalCount > 0) {
79	                const wr = Math.round((aiWins / evalCount) * 100);
80	                let wrColor = 'var(--text-muted)';
81	                if (wr > 50) wrColor = 'var(--success)';
82	                else if (wr < 50) wrColor = 'var(--danger)';
83	                else wrColor = 'var(--warning)';
84	
85	                winrateHtml = `<span style="font-size: 0.85em; font-weight: normal; color: ${wrColor};">WR: ${wr}% (${aiWins}/${evalCount})</span>`;
86	            }
87	
88	            const eloText = group.elo ? `<span style="color: var(--text-muted); font-size: 0.85em; font-weight: normal; margin-left: 0.5rem;">(~${group.elo} Elo)</span>` : '';
89	
90	            details.innerHTML = `<summary style="display: flex; justify-content: space-between; align-items: center;">
91	                <span>Iteration ${group.iteration}${eloText}</span>
92	                ${winrateHtml}
93	            </summary>`;
94	
95	            // Sort games: eval games first, then by game index
96	            group.games.sort((a, b) => {
97	                if (a.is_eval && !b.is_eval) return -1;
98	                if (!a.is_eval && b.is_eval) return 1;
99	                return a.game_index - b.game_index;
100	            });
101	
102	            group.games.forEach(game => {
103	                const item = document.createElement('div');
104	                item.className = 'game-item review-list-item';
105	
106	                // Highlight if currently selected
107	                if (currentGameData && currentGameData.filename === game.filename) {
108	                    item.classList.add('active');
109	                }
110	
111	                const winnerIcon = game.winner === 1 ? '⚫' : (game.winner === 2 ? '⚪' : '🤝');
112	                let label = '';
113	
114	                if (game.is_eval) {
115	                    const aiColorStr = game.network_color === 1 ? '⚫ Black' : '⚪ White';
116	                    label = `Eval #${game.game_index} (AI as ${aiColorStr} vs RandomBot)`;
117	                } else {
118	                    label = `Self-Play #${game.game_index}`;
119	                }
120	
121	                let resultText = 'Draw';
122	                if (game.winner === 1) resultText = `B+${game.margin !== undefined ? Number(game.margin).toFixed(1) : '?'}`;
123	                else if (game.winner === 2) resultText = `W+${game.margin !== undefined ? Number(game.margin).toFixed(1) : '?'}`;
124	
125	                let resultColor = 'var(--text-muted)';
126	                if (game.is_eval && game.network_color !== undefined && game.winner !== 0) {
127	                    resultColor = (game.winner === game.network_color) ? 'var(--success)' : 'var(--danger)';
128	                }
129	
130	                item.innerHTML = `
131	                    <div style="display: flex; justify-content: space-between; margin-bottom: 0.25rem;">
132	                        <strong>${winnerIcon} ${label}</strong>
133	                    </div>
134	                    <div style="display: flex; justify-content: space-between; font-size: 0.85rem; color: var(--text-muted);">
135	                        <span><span style="color: ${resultColor}; font-weight: 600;">${resultText}</span> &middot; ${game.num_moves} moves</span>
136	                        <span>${new Date(game.timestamp).toLocaleTimeString()}</span>
137	                    </div>
138	                `;
139	
140	                item.addEventListener('click', () => {
141	                    document.querySelectorAll('.game-item').forEach(el => el.classList.remove('active'));
142	                    item.classList.add('active');
143	
144	                    const url = new URL(window.location);
145	                    url.searchParams.set('game', game.filename);
146	                    window.history.pushState({}, '', url);
147	
148	                    loadGame(game.filename);
149	                });
150	
151	                details.appendChild(item);
152	            });
153	            list.appendChild(details);
154	        });
155	    } catch (e) {
156	        list.innerHTML = '<p style="color: var(--text-muted); text-align: center;">Error loading games.</p>';
157	    }
158	}
