160	async function loadGame(filename) {
161	    try {
162	        const cacheBuster = new Date().getTime();
163	        const res = await fetch(`/training/api/games/${filename}?t=${cacheBuster}`);
164	        if (!res.ok) throw new Error('Game not found');
165	
166	        const data = await res.json();
167	        data.filename = filename;
168	        currentGameData = data;
169	
170	        document.getElementById('empty-state').style.display = 'none';
171	        document.getElementById('review-viewer').style.display = 'block';
172	
173	        const canvas = document.getElementById('review-board');
174	        const size = data.board_size || 9;
175	
176	        reviewBoard = new GoBoardRenderer(canvas, size);
177	
178	        // Informative Game Title & Meta
179	        let titleText = '';
180	        let resultText = '';
181	        const komi = data.komi || 6.5;
182	
183	        if (data.winner === 1) resultText = `Black wins (B+${data.margin !== undefined ? Number(data.margin).toFixed(1) : '?'})`;
184	        else if (data.winner === 2) resultText = `White wins (W+${data.margin !== undefined ? Number(data.margin).toFixed(1) : '?'})`;
185	        else resultText = 'Draw';
186	
187	        if (data.is_eval) {
188	            const aiColor = data.network_color === 1 ? '⚫ Black' : '⚪ White';
189	            const randColor = data.network_color === 1 ? '⚪ White' : '⚫ Black';
190	            const outcomeStr = (data.winner === data.network_color) ? '🎉 Go AI Won' : '❌ RandomBot Won';
191	            titleText = `Iteration ${data.iteration} · Eval Match #${data.game_index || 1}`;
192	            document.getElementById('review-meta').innerHTML = `<strong>${outcomeStr}</strong> (${resultText}) &middot; Go AI (${aiColor}) vs RandomBot (${randColor}) &middot; ${data.moves.length} moves &middot; Komi ${komi}`;
193	        } else {
194	            titleText = `Iteration ${data.iteration} · Self-Play Game #${data.game_index || 1}`;
195	            document.getElementById('review-meta').innerHTML = `<strong>${resultText}</strong> &middot; ${data.moves.length} moves &middot; Komi ${komi}`;
196	        }
197	
198	        document.getElementById('review-title').textContent = titleText;
199	
200	        initWinrateChart(data);
201	
202	        jumpToMove(0);
203	
204	    } catch (e) {
205	        alert("Failed to load game: " + filename);
206	    }
207	}
208	
209	// Palette per perspective so the curve's color reinforces whose win % is shown.
210	const WINRATE_STYLE = {
211	    1: { name: 'Black', line: '#c8956c', fill: 'rgba(200, 149, 108, 0.12)', point: '#dbb08a' },
212	    2: { name: 'White', line: '#cdd3dd', fill: 'rgba(205, 211, 221, 0.12)', point: '#e8ebf0' },
213	};
214	
215	/** Series for the currently selected perspective (White = 100 − Black). */
216	function winrateSeries() {
217	    return winrateSide === 2
218	        ? winrateBlack.map((v) => Math.round((100 - v) * 10) / 10)
219	        : winrateBlack.slice();
220	}
221	
222	/** Build (or rebuild) the per-move win-rate line chart for the loaded game. */
223	function initWinrateChart(data) {
224	    const container = document.getElementById('review-winrate-container');
225	    const canvas = document.getElementById('review-winrate-chart');
226	    if (!container || !canvas || typeof Chart === 'undefined') return;
227	
228	    if (winrateChart) {
229	        winrateChart.destroy();
230	        winrateChart = null;
231	    }
232	
233	    winrateBlack = Array.isArray(data.win_rates) ? data.win_rates : [];
234	    if (winrateBlack.length === 0) {
235	        // No eval data available (e.g. board-size mismatch) — hide the chart.
236	        container.style.display = 'none';
237	        return;
238	    }
239	    container.style.display = 'block';
240	
241	    // Default perspective: for eval games (AI vs RandomBot), show the AI's side;
242	    // otherwise default to Black.
243	    if (data.is_eval && (data.network_color === 1 || data.network_color === 2)) {
244	        winrateSide = data.network_color;
245	    } else {
246	        winrateSide = 1;
247	    }
248	
249	    const labels = winrateBlack.map((_, i) => i);
250	    const style = WINRATE_STYLE[winrateSide];
251	    const series = winrateSeries();
252	    const gridColor = 'rgba(255, 255, 255, 0.06)';
253	    const tickColor = '#9a9a9a';     // --text-secondary
254	
255	    winrateChart = new Chart(canvas.getContext('2d'), {
256	        type: 'line',
257	        data: {
258	            labels,
259	            datasets: [{
260	                label: `${style.name} Win %`,
261	                data: series,
262	                borderColor: style.line,
263	                backgroundColor: style.fill,
264	                borderWidth: 2,
265	                fill: true,
266	                tension: 0.35,
267	                pointRadius: series.map(() => 0),
268	                pointHoverRadius: 5,
269	                pointBackgroundColor: style.point,
270	                pointBorderColor: style.point,
271	            }],
272	        },
273	        options: {
274	            responsive: true,
275	            maintainAspectRatio: false,
276	            animation: false,
277	            interaction: { mode: 'index', intersect: false },
278	            onClick: (evt, elements, chart) => {
279	                // `elements` is already resolved via the configured index/no-intersect
280	                // interaction; fall back to an explicit lookup just in case.
281	                let idx = (elements && elements.length) ? elements[0].index : null;
282	                if (idx === null) {
283	                    const pts = chart.getElementsAtEventForMode(evt, 'index', { intersect: false }, true);
284	                    if (pts.length > 0) idx = pts[0].index;
285	                }
286	                if (idx !== null) jumpToMove(idx);
287	            },
288	            plugins: {
289	                legend: { display: false },
290	                tooltip: {
291	                    callbacks: {
292	                        title: (items) => `Move ${items[0].label}`,
293	                        label: (item) => `${WINRATE_STYLE[winrateSide].name}: ${Number(item.raw).toFixed(1)}%`,
294	                    },
295	                },
296	            },
297	            scales: {
298	                x: {
299	                    title: { display: true, text: 'Move Number', color: tickColor },
300	                    grid: { color: gridColor },
301	                    ticks: { color: tickColor, maxTicksLimit: 12 },
302	                },
303	                y: {
304	                    min: 0,
305	                    max: 100,
306	                    title: { display: true, text: `${style.name} Win %`, color: tickColor },
307	                    grid: { color: gridColor },
308	                    ticks: { color: tickColor, stepSize: 25, callback: (v) => `${v}%` },
309	                },
310	            },
311	        },
312	    });
313	
314	    updateWinrateSideButtons();
315	}
316	
317	/** Switch the chart between Black's and White's perspective. */
318	function setWinrateSide(side) {
319	    if (side === winrateSide) return;
320	    winrateSide = side;
321	    if (!winrateChart) {
322	        updateWinrateSideButtons();
323	        return;
324	    }
325	
326	    const style = WINRATE_STYLE[side];
327	    const ds = winrateChart.data.datasets[0];
328	    ds.data = winrateSeries();
329	    ds.label = `${style.name} Win %`;
330	    ds.borderColor = style.line;
331	    ds.backgroundColor = style.fill;
332	    ds.pointBorderColor = style.point;
333	    winrateChart.options.scales.y.title.text = `${style.name} Win %`;
334	    winrateChart.update('none');
335	
336	    updateWinrateSideButtons();
337	    highlightWinrateMove(currentMoveIndex);
338	}
339	
340	/** Reflect the active perspective on the toggle buttons. */
341	function updateWinrateSideButtons() {
342	    const btnB = document.getElementById('winrate-side-black');
343	    const btnW = document.getElementById('winrate-side-white');
344	    [[btnB, 1], [btnW, 2]].forEach(([btn, side]) => {
345	        if (!btn) return;
346	        const on = side === winrateSide;
347	        btn.style.background = on ? 'var(--accent)' : 'transparent';
348	        btn.style.color = on ? '#fff' : 'var(--text-secondary)';
349	    });
350	}
351	
352	/** Emphasize the dot for the active move on the win-rate chart. */
353	function highlightWinrateMove(index) {
354	    const label = document.getElementById('winrate-current');
355	    if (!winrateChart) {
356	        if (label) label.textContent = '';
357	        return;
358	    }
359	    const style = WINRATE_STYLE[winrateSide];
360	    const data = winrateChart.data.datasets[0].data;
361	    // The chart has a point per move (0 .. n-1); the terminal position (index n)
362	    // has no eval, so clamp the highlight to the last available point.
363	    const active = Math.min(index, data.length - 1);
364	
365	    winrateChart.data.datasets[0].pointRadius = data.map((_, i) => (i === active ? 5 : 0));
366	    winrateChart.data.datasets[0].pointBackgroundColor = data.map((_, i) => (i === active ? '#fff' : style.point));
367	    winrateChart.update('none');
368	
369	    if (label && active >= 0 && active < data.length) {
370	        label.textContent = `${style.name} @ move ${active}: ${Number(data[active]).toFixed(1)}%`;
371	    } else if (label) {
372	        label.textContent = '';
373	    }
374	}
375	
376	function jumpToMove(index) {
377	    if (!currentGameData || !reviewBoard) return;
378	
379	    currentMoveIndex = Math.max(0, Math.min(index, currentGameData.moves.length));
380	
381	    if (currentGameData.states && currentGameData.states[currentMoveIndex]) {
382	        reviewBoard.grid = currentGameData.states[currentMoveIndex];
383	    } else {
384	        const size = currentGameData.board_size;
385	        reviewBoard.grid = Array.from({ length: size }, () => Array(size).fill(0));
386	    }
387	
388	    let lastMove = null;
389	    if (currentMoveIndex > 0) {
390	        const m = currentGameData.moves[currentMoveIndex - 1];
391	        if (m.move[0] >= 0 && m.move[1] >= 0) {
392	            lastMove = { row: m.move[0], col: m.move[1] };
393	        }
394	    }
395	
396	    reviewBoard.lastMove = lastMove;
397	
398	    // Territory Estimation Overlay & Live Breakdown
399	    const breakdownEl = document.getElementById('territory-breakdown');
400	    if (showTerritory) {
401	        const est = reviewBoard.computeTerritory(currentGameData.komi || 6.5);
402	        reviewBoard.showEstimate = true;
403	        if (breakdownEl) {
404	            let atariNote = '';
405	            if (est.atariStonesBlack > 0 || est.atariStonesWhite > 0) {
406	                const parts = [];
407	                if (est.atariStonesBlack > 0) parts.push(`⚫ ${est.atariStonesBlack} Black stone(s)`);
408	                if (est.atariStonesWhite > 0) parts.push(`⚪ ${est.atariStonesWhite} White stone(s)`);
409	                atariNote = `<br><span style="color: var(--warning); font-size: 0.82rem; margin-top: 0.2rem; display: inline-block;">⚠️ Atari Alert: ${parts.join(' & ')} currently in Atari (1 liberty) — once captured, true score shifts!</span>`;
410	            }
411	
412	            breakdownEl.style.display = 'block';
413	            breakdownEl.innerHTML = `
414	                <strong>🗺 Live Territory Estimation (Move ${currentMoveIndex})</strong><br>
415	                ⚫ <strong>Black: ${est.blackScore.toFixed(1)} pts</strong> (${est.blackStones} stones + ${est.blackTerritory} territory)<br>
416	                ⚪ <strong>White: ${est.whiteScore.toFixed(1)} pts</strong> (${est.whiteStones} stones + ${est.whiteTerritory} territory + ${est.komi} komi)<br>
417	                <span style="color: var(--accent-light); font-weight: 600; margin-top: 0.25rem; display: inline-block;">Estimated Lead: ${est.lead}</span>
418	                ${atariNote}
419	            `;
420	        }
421	    } else {
422	        reviewBoard.showEstimate = false;
423	        reviewBoard.ownershipMap = null;
424	        if (breakdownEl) breakdownEl.style.display = 'none';
425	    }
426	
427	    reviewBoard.draw();
428	
429	    highlightWinrateMove(currentMoveIndex);
430	
431	    const curStr = String(currentMoveIndex).padStart(3, '\u00A0');
432	    const totalStr = String(currentGameData.moves.length).padStart(3, '\u00A0');
433	    document.getElementById('move-counter').textContent = `${curStr} / ${totalStr}`;
434	
435	    document.getElementById('btn-first').disabled = currentMoveIndex === 0;
436	    document.getElementById('btn-prev').disabled = currentMoveIndex === 0;
437	    document.getElementById('btn-next').disabled = currentMoveIndex === currentGameData.moves.length;
438	    document.getElementById('btn-last').disabled = currentMoveIndex === currentGameData.moves.length;
439	}
440	
441	window.addEventListener('resize', () => {
442	    if (reviewBoard) {
443	        reviewBoard.resize();
444	    }
445	});
446	
447	document.addEventListener('keydown', (e) => {
448	    if (!currentGameData || !reviewBoard) return;
449	    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
450	
451	    if (e.key === 'ArrowLeft') {
452	        e.preventDefault();
453	        const step = e.shiftKey ? 10 : 1;
454	        jumpToMove(currentMoveIndex - step);
455	    } else if (e.key === 'ArrowRight') {
456	        e.preventDefault();
457	        const step = e.shiftKey ? 10 : 1;
458	        jumpToMove(currentMoveIndex + step);
459	    }
460	});
